from dash import html
from app import queries as q,figures as f
from app.components.common import *

def render(s,states,dark):
    eu=q.theme_shares(s,'EU');af=q.theme_shares(s,'AFNC');ai=q.aiid(s,True);a=q.afnc(s,False);e=q.eu_items(s);ev=q.evidence('2',s)
    # Stacked category context obeys shared time and AFNC category; selected theme applies too.
    period=breadcrumb('2',s);all_af=q.afnc({**s,'theme':None},False);wh,args=q.time_where(s);all_eu=int(q.query(f'SELECT COUNT(*) n FROM eu_debunk WHERE {wh}',args).iloc[0,0]);e_den=int(eu[['year','denominator']].drop_duplicates().denominator.sum());a_den=int(af[['year','denominator']].drop_duplicates().denominator.sum())
    return html.Div([html.P('02 / ประเด็นต่างประเทศกับไทย',className='eyebrow'),html.H1('ประเด็นที่ปรากฏร่วมกัน'),html.P('ประเด็นใดปรากฏร่วม และมีสัดส่วนต่างกันอย่างไร? ไม่ใช่หลักฐานการแพร่ข้ามประเทศ'),filters('2',s),html.P('AFNC ปี 2562 ไม่เต็มปี · EUvsDisinfo ถึง 1 ส.ค. 2566 เท่านั้น หลังจากนั้นไม่มีข้อมูล · 1 เรื่องอยู่ได้หลายประเด็น ผลรวมอาจเกิน 100%',className='notice'),html.Div([kpi('K2 · EU ทั้งแหล่งในช่วง',number(all_eu) if all_eu else 'ไม่มีข้อมูล','การหักล้าง','EUvsDisinfo',period),kpi('K2 · AFNC ข่าวเท็จในช่วง',number(len(all_af)),'โพสต์ข่าวเท็จ','AFNC',period),kpi('K2 · บริบท Misinformation',number(len(ai)),'เหตุการณ์','AIID',period)],className='kpi-grid three'),html.P(f'ฐานสัดส่วนทั้งช่วง: EU {e_den:,} การหักล้าง / AFNC {a_den:,} ข่าวเท็จ · ไม่เปลี่ยนเป็นฐานเฉพาะประเด็น'),html.Div([panel('C2.1 · EUvsDisinfo',graph('heatEU',f.heatmap(eu,s,dark)),'ฝั่งสนับสนุนรัสเซีย ไม่ใช่ข่าวปลอมทั้งหมดทั่วโลก · หมวด AFNC ไม่มีผลกับกราฟนี้'),panel('C2.2 · AFNC',graph('heatAF',f.heatmap(af,s,dark)),'สุขภาพ การเงิน การเมือง: วิธีจัดกลุ่มต่างกัน (AFNC จัดตามหมวด EU ตาม keyword)')],className='grid-2'),html.Div([panel('C2.3 · สัดส่วนประเด็นที่เลือก',graph('theme2',f.theme_line(eu,af,s,dark)),'ตัวหารเป็นทุกเรื่องในแหล่งและปีเดียวกัน'),panel('C2.4 · หมวดข่าวเท็จ AFNC',graph('stack2',f.stacked_categories(a,s,dark)))],className='grid-2'),panel('C2.5 · บริบท AIID Misinformation',graph('misinfo2',f.timeseries(ai,s,'Misinformation',dark)),'ตัวกรองประเด็นและหมวดไม่มีผลกับ AIID'),panel('T2 · หลักฐานในประเด็นและช่วงเดียวกัน',[download('2',states),html.P('ไม่ใช่การจับคู่ข่าวต่อข่าว'),html.Div([html.Div([html.H4('AFNC'),table(ev,'2',s,source='AFNC')]),html.Div([html.H4('EUvsDisinfo'),table(ev,'2',s,source='EUvsDisinfo')])],className='grid-2')]),summary(f'ในประเด็น {THEMES[s["theme"]][0]} และตัวกรองรายการปัจจุบัน พบ EU {len(e):,} การหักล้าง กับ AFNC {len(a):,} โพสต์ ทั้งสองแหล่งมีฐานการคัดเลือกต่างกัน','ไม่มีคีย์เชื่อมข่าวต่อข่าว ความถี่ไม่ได้วัดการนำเข้า ประเด็นความขัดแย้งอื่นไม่เท่ากับยูเครน และสุขภาพ/การเงิน/การเมืองใช้วิธีจัดกลุ่มต่างกัน')])
